/* LEADCTRL v1 — local-first web app. No backend, analytics, or automatic messaging. */
(() => {
'use strict';
const STORE_KEY='leadctrl-workspace-v1';
const STATUS=['new','contacted','quoted','won','lost'];
const COLORS={new:'#95adee',contacted:'#79b7b8',quoted:'#b5a0db',won:'#8ec17c',lost:'#d7a4aa'};
const ICONS={
 trend:'<path d="m3 17 6-6 4 4 8-8"/><path d="M15 7h6v6"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.6"/><rect x="14" y="3" width="7" height="7" rx="1.6"/><rect x="3" y="14" width="7" height="7" rx="1.6"/><rect x="14" y="14" width="7" height="7" rx="1.6"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 settings:'<path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.05.06-1.9 1.9-.06-.05a1.7 1.7 0 0 0-1.9-.3l-.1.05V21h-2.7v-.13a1.7 1.7 0 0 0-1.1-1.6 1.7 1.7 0 0 0-1.9.3l-.05.05-1.9-1.9.05-.05a1.7 1.7 0 0 0 .3-1.9l-.05-.1H6v-2.7h.13a1.7 1.7 0 0 0 1.6-1.1 1.7 1.7 0 0 0-.3-1.9l-.05-.05 1.9-1.9.05.05a1.7 1.7 0 0 0 1.9.3l.1-.05V6h2.7v.13a1.7 1.7 0 0 0 1.1 1.6 1.7 1.7 0 0 0 1.9-.3l.05-.05 1.9 1.9-.05.05a1.7 1.7 0 0 0-.3 1.9l-.05.1H21v2.7h-.13a1.7 1.7 0 0 0-1.47.97Z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',chev:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',x:'<path d="M18 6 6 18M6 6l12 12"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.5 3a2 2 0 0 1-.6 1.8L7.1 10a16 16 0 0 0 6.9 6.9l1.5-1.9a2 2 0 0 1 1.8-.6l3 .5a2 2 0 0 1 1.7 2Z"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M5 17v4h14v-4"/>',trash:'<path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3"/>',
 edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41M2 12h2m16 0h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',receipt:'<path d="M4 3h16v18l-4-2-4 2-4-2-4 2V3Z"/><path d="M8 8h8M8 12h8"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 13h18"/>',
 spark:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8L12 3ZM19 19l1 3 1-3 2-1-2-1-1-3-1 3-2 1 2 1"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',
 print:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v7H6z"/>',
 filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',external:'<path d="M14 4h6v6M20 4l-9 9M20 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h5"/>',
 repeat:'<path d="m16 3 4 4-4 4M20 7H8a4 4 0 0 0-4 4v1M8 21l-4-4 4-4M4 17h12a4 4 0 0 0 4-4v-1"/>',
 dot:'<circle cx="12" cy="12" r="2"/>'
};
const ico=(name,cls='')=>`<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24">${ICONS[name]||ICONS.dot}</svg></span>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)||0);
const moneyExact=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const offset=(days)=>{let d=new Date();d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const datefmt=s=>{if(!s)return 'Not set';let d=new Date(s+'T12:00:00');return isNaN(d)?'Not set':d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})};
const shortdate=s=>{if(!s)return '—';let d=new Date(s+'T12:00:00');return isNaN(d)?'—':d.toLocaleDateString('en-US',{month:'short',day:'numeric'})};
const nowstamp=()=>new Date().toISOString();
const randId=()=> typeof crypto!=='undefined' && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2,9)}`;
const blankStore=()=>({version:1,business:{name:'',owner:'',email:'',phone:'',service:'Home services'},leads:[],quotes:[],demo:false,activities:[]});
let store;try{store=JSON.parse(localStorage.getItem(STORE_KEY))}catch{};if(!store||!store.business||!Array.isArray(store.leads)||!Array.isArray(store.quotes))store=blankStore();
const ui={mode:store.business.name?'app':'welcome',view:'overview',modal:null,search:'',filter:'all',sidebar:false,quoteLines:[],quoteLead:'',draftQuote:null};
let toastTimer=null;
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(store));return true}catch(e){toast('Could not save. Export a backup; device storage may be full.');return false}}
function activity(kind,title){store.activities.unshift({id:randId(),kind,title,at:nowstamp()});store.activities=store.activities.slice(0,60)}
function getLead(id){return store.leads.find(l=>l.id===id)}
function getQuote(id){return store.quotes.find(q=>q.id===id)}
function badge(s){return `<span class="badge ${esc(s)}">${esc((s||'').charAt(0).toUpperCase()+(s||'').slice(1))}</span>`}
function initials(name){return (name||'LC').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase().slice(0,2)}
function logo(){return `<div class="brandmark">${ico('trend','lg')}</div>`}
function toast(message){const host=document.getElementById('toast-region');host.innerHTML=`<div class="toast">${ico('check')}${esc(message)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>host.innerHTML='',3800)}
const activeLead=l=>l.status!=='won'&&l.status!=='lost';
const pending=()=>store.leads.filter(l=>activeLead(l)&&l.followUpDate&&!l.followUpDone).sort((a,b)=>a.followUpDate.localeCompare(b.followUpDate));
const overdue=()=>pending().filter(l=>l.followUpDate<today());
const due=()=>pending().filter(l=>l.followUpDate<=today());
const pipe=()=>store.leads.filter(activeLead).reduce((x,l)=>x+(+l.value||0),0);
const won=()=>store.leads.filter(l=>l.status==='won').reduce((x,l)=>x+(+l.value||0),0);
function topbar(){const labels={overview:'Overview',leads:'Leads',quotes:'Quotes',followups:'Follow-ups',settings:'Settings'};
return `<header class="topbar"><div class="top-left"><button type="button" class="mobile-menu" data-action="toggle-menu" aria-label="Open menu">${ico('menu')}</button><div class="crumb"><span>Workspace</span><span class="slash">/</span><strong>${labels[ui.view]}</strong></div></div><div class="top-right"><span class="top-date">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><button class="top-icon" type="button" data-action="nav" data-view="followups" aria-label="Follow-ups">${ico('bell')}</button><button class="btn" data-action="add-lead">${ico('plus')} New lead</button></div></header>`}
function sidebar(){let nav=[['overview','grid','Overview'],['leads','users','Leads'],['quotes','receipt','Quotes'],['followups','clock','Follow-ups'],['settings','settings','Settings']];return `<aside class="sidebar ${ui.sidebar?'open':''}" aria-label="Primary navigation"><div class="brand">${logo()}<div class="brandword">LEAD<span>CTRL</span></div></div><div class="sidebarlabel">Your workspace</div><nav class="nav">${nav.map(([id,icon,label])=>`<button type="button" class="navitem ${ui.view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}<span>${label}</span>${id==='followups'&&due().length?`<span class="navnum">${due().length}</span>`:ui.view===id?ico('chev','sm navchev'):''}</button>`).join('')}</nav><div class="sidebottom"><div class="sideupgrade"><strong>${ico('spark','sm')} Every lead counts.</strong><p>Turn forgotten inquiries into booked jobs. Your pipeline lives here.</p><button data-action="add-lead" type="button">${ico('plus','sm')} Add an opportunity</button></div><div class="identity"><div class="avatar">${esc(initials(store.business.name))}</div><div style="min-width:0"><strong>${esc(store.business.name)}</strong><span>${store.demo?'Sample data · Explore mode':'Local workspace · Free'}</span></div></div></div></aside>`}
function bottomnav(){let n=[['overview','grid','Home'],['leads','users','Leads'],['quotes','receipt','Quotes'],['followups','clock','Follow up'],['settings','settings','More']];return `<nav class="floating-mobile" aria-label="Mobile navigation">${n.map(([id,icon,label])=>`<button type="button" class="float-nav ${ui.view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}<span>${label}</span></button>`).join('')}</nav>`}
function appShell(){const views={overview:overviewPage,leads:leadsPage,quotes:quotesPage,followups:followupsPage,settings:settingsPage};return `<div class="layout">${sidebar()}<main class="main">${topbar()}${views[ui.view]()}${bottomnav()}</main></div>${ui.modal?modal():''}`}
function welcomePage(){return `<main class="welcome"><div class="welcome-header"><div class="brand">${logo()}<div class="brandword">LEAD<span>CTRL</span></div></div><div class="eyebrow">THE SIMPLE SALES WORKSPACE</div></div><section class="welcome-main"><div><span class="micro">YOUR BUSINESS. FULLY IN CONTROL.</span><h1>Less chasing.<br><em>More closing.</em></h1><p>That customer who asked for a quote three days ago? Don't lose them. Keep leads, quotes, and follow-ups in one ridiculously simple workspace—made for people who run the business *and* do the work.</p><div class="welcome-cta"><button class="btn lime" data-action="start-setup">Build my workspace ${ico('arrow')}</button><button class="btn outline" data-action="start-demo">Explore live demo ${ico('arrow')}</button></div><div class="welcome-foot">${ico('lock','sm')} No signup. No credit card. Local-first and free.</div></div><div class="hero-preview" aria-label="Illustrative app preview"><div class="hero-head"><div><small>YOUR WORKSPACE</small><strong>Pipeline overview</strong></div><span style="background:#e5f2d6;color:#5f845a;border-radius:40px;padding:6px 9px;font-size:9px;font-weight:900">● Live view</span></div><div class="hero-metrics"><div><span>OPEN PIPELINE</span><strong>$8,450</strong><small style="color:#7c9588">Example data</small></div><div><span>ACTIVE LEADS</span><strong>12</strong><small style="color:#7c9588">Example data</small></div></div><div class="hero-task"><div class="hero-task-label">NEXT OPPORTUNITY</div><strong>Driveway pressure washing</strong><p>Follow up with a customer who requested a $320 quote.</p><button type="button" data-action="start-demo">See it in action ${ico('arrow','sm')}</button></div><div style="padding:18px 2px 1px;display:flex;gap:6px;align-items:center"><span style="width:25%;height:8px;background:#82b1b3;border-radius:8px"></span><span style="width:33%;height:8px;background:#b5a0d9;border-radius:8px"></span><span style="width:18%;height:8px;background:#9ac880;border-radius:8px"></span><span style="width:24%;height:8px;background:#e8eee9;border-radius:8px"></span></div></div></section><footer class="welcome-bottom"><b>LEADCTRL / v1.0</b><span>Built for detailers, landscapers, cleaners & service pros.</span><span>Everything you need to follow through.</span></footer></main>`}
function setupPage(){return `<main class="setup-wrap"><form class="setup-card" id="setup-form">${logo()}<span class="eyebrow">ONE-MINUTE SETUP</span><h1>Let's make it yours.</h1><p>Set up your workspace. Everything you enter is saved locally on this device.</p><div class="field"><label for="busname">Business name *</label><input id="busname" name="name" required maxlength="90" placeholder="e.g. Northside Detailing"></div><div class="field"><label for="ownername">Your first name</label><input id="ownername" name="owner" maxlength="70" placeholder="e.g. Alex"></div><div class="field"><label for="bustype">Type of business</label><select id="bustype" name="service"><option>Home services</option><option>Auto detailing</option><option>Lawn care & landscaping</option><option>Pressure washing</option><option>Cleaning</option><option>Other services</option></select></div><button class="btn lime" type="submit">Open workspace ${ico('arrow')}</button><p class="foot">${ico('lock','sm')} No account needed. You can export backups at any time.</p><button type="button" class="linkbtn" data-action="back-welcome">← Back</button></form></main>`}
function heading(eyebrow,title,desc,action=''){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="head-actions">${action}</div>`:''}</div>`}
function metric(label,value,icon,foot,dot=''){return `<article class="metric"><div class="metric-top"><span>${esc(label)}</span><div class="metric-ic">${ico(icon)}</div></div><div class="metric-val tabular">${value}</div><div class="metric-bottom">${dot?`<i class="${dot}"></i>`:''}${foot}</div></article>`}
function overviewPage(){let first=store.business.owner?.trim()?.split(' ')[0];let pipeline=STATUS.map(s=>({name:s,count:store.leads.filter(l=>l.status===s).length,color:COLORS[s]}));let total=store.leads.length||1;let recent=[...store.leads].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5);let tasks=due().slice(0,4);
return `<div class="page"><div class="page-head"><div><div class="daytag">${ico('sun','sm')} ${new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}</div><h1 class="big-hello">Let's close some jobs${first?', '+esc(first):''}<span>.</span></h1><p class="head-desc">Your business at a glance. Every opportunity, one place.</p></div><div class="head-actions"><button class="btn outline" data-action="add-quote">${ico('receipt')} New quote</button><button class="btn" data-action="add-lead">${ico('plus')} Add lead</button></div></div>${store.demo?`<div class="info-note" style="margin-bottom:15px">${ico('info','sm')} You're exploring with <b>sample data</b>. None of these customers are real. Use Settings → Clear sample data to start fresh.</div>`:''}<section class="cards4" aria-label="Business performance">${metric('OPEN PIPELINE',money(pipe()),'trend','Value of active opportunities','dotgood')}${metric('ACTIVE LEADS',store.leads.filter(activeLead).length,'users','New, contacted and quoted')}${metric('WON JOB VALUE',money(won()),'briefcase','Based on leads marked won','dotgood')}${metric('NEEDS FOLLOW-UP',due().length,'clock',`${overdue().length} overdue • ${due().length-overdue().length} due today`,due().length?'dotwarn':'dotgood')}</section><div class="dashgrid"><div class="stack"><section class="panel panel-pad"><div class="panel-top"><div><h2>Your sales pipeline</h2><div class="panel-sub">Where each opportunity stands</div></div><button class="panel-link" data-action="nav" data-view="leads">All leads ${ico('arrow','sm')}</button></div><div class="pipeline-bar" aria-label="Lead stages">${pipeline.map(p=>`<div style="width:${p.count/total*100}%;background:${p.color}" title="${p.name}: ${p.count}"></div>`).join('')}</div><div class="pipeline-grid">${pipeline.map(p=>`<div class="pipeline-cell"><strong>${p.count}</strong><span>${p.name.charAt(0).toUpperCase()+p.name.slice(1)}</span></div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-top"><div><h2>Recent opportunities</h2><div class="panel-sub">Your latest inbound work</div></div><button class="panel-link" data-action="nav" data-view="leads">View all ${ico('arrow','sm')}</button></div>${recent.length?recent.map(l=>`<div class="lead-row" data-action="view-lead" data-id="${l.id}" role="button" tabindex="0"><div class="lead-main"><div class="miniavatar">${esc(initials(l.name))}</div><div style="min-width:0"><strong>${esc(l.name)}</strong><p>${esc(l.service||'Service inquiry')} · ${esc(shortdate(l.createdAt.slice(0,10)))}</p></div></div><div class="lead-right"><strong>${money(l.value)}</strong><div style="margin-top:5px">${badge(l.status)}</div></div></div>`).join(''):`<div class="empty-state"><div class="empty-art">${ico('users','lg')}</div><h3>No leads just yet</h3><p>Add your first customer inquiry and start building a real pipeline.</p><button class="btn" data-action="add-lead">${ico('plus')} Add first lead</button></div>`}</section></div><div class="stack"><section class="panel panel-pad"><div class="panel-top"><div><h2>Follow-up priority</h2><div class="panel-sub">Don't let an opportunity go cold</div></div>${due().length?`<span class="badge overdue">${due().length} due</span>`:''}</div>${tasks.length?tasks.map(l=>`<div class="task"><div class="task-icon">${ico('clock')}</div><div class="task-body"><strong>${esc(l.name)}</strong><p>${l.followUpDate<today()?'Overdue': 'Due today'} · ${esc(l.service||'General inquiry')}</p></div><button class="btn small soft" data-action="view-lead" data-id="${l.id}">Open</button></div>`).join(''):`<div class="miniempty">${ico('check','lg')}<br>You're all caught up.<br>No follow-ups due right now.</div>`}<button class="linkbtn" style="margin-top:16px;font-size:10px" data-action="nav" data-view="followups">Open follow-up list ${ico('arrow','sm')}</button></section><section class="panel panel-pad right-feature"><div><div class="chip">QUOTE IN MINUTES</div><h2>Make the next yes easy.</h2><p>Create a clean estimate, then send it straight from your email app.</p></div><button class="btn lime" data-action="add-quote">Create a quote ${ico('arrow','sm')}</button></section><section class="panel panel-pad"><div class="panel-top"><div><h2>Built for the day-to-day.</h2><div class="panel-sub">A tiny system that keeps you moving</div></div>${ico('spark')}</div><p style="font-size:11px;color:#87969a;line-height:1.9;margin:0">Add inquiries as they come in. Put a date on every next step. Send a quote, then follow through. The goal isn't more software. It's more booked jobs.</p></section></div></div></div>`}
function leadsPage(){let filtered=store.leads.filter(l=>(ui.filter==='all'||l.status===ui.filter)&&(`${l.name} ${l.company} ${l.service} ${l.email} ${l.phone}`.toLowerCase().includes(ui.search.toLowerCase()))).sort((a,b)=>(b.updatedAt||b.createdAt).localeCompare(a.updatedAt||a.createdAt));return `<div class="page">${heading('OPPORTUNITY TRACKER','Every lead. One place.','Capture requests, track their status, and never forget to follow up.',`<button class="btn" data-action="add-lead">${ico('plus')} Add new lead</button>`)}<div class="toolbar"><div class="searchbox">${ico('search','sm')}<input id="lead-search" value="${esc(ui.search)}" placeholder="Search name, service, email..." autocomplete="off" aria-label="Search leads"></div><div class="filters">${['all',...STATUS].map(s=>`<button class="filter ${ui.filter===s?'active':''}" data-action="filter" data-status="${s}">${s==='all'?'All leads':s.charAt(0).toUpperCase()+s.slice(1)}</button>`).join('')}</div></div><section class="panel"><div class="table-wrap">${filtered.length?`<table class="data-table"><thead><tr><th>Customer</th><th>Service</th><th>Value</th><th>Status</th><th>Next follow-up</th><th class="txt-right">View</th></tr></thead><tbody>${filtered.map(l=>`<tr data-open="${l.id}" tabindex="0"><td><div class="namepair"><strong>${esc(l.name)}</strong><small>${esc(l.company||l.email||l.phone||'New contact')}</small></div></td><td>${esc(l.service||'—')}</td><td class="value">${money(l.value)}</td><td>${badge(l.status)}</td><td>${l.followUpDate?`<span class="${!l.followUpDone&&l.followUpDate<today()?'em':''}">${esc(shortdate(l.followUpDate))}${l.followUpDone?' ✓':''}</span>`:'—'}</td><td class="txt-right">${ico('chev','sm')}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><div class="empty-art">${ico('search','lg')}</div><h3>${store.leads.length?'No matching leads':'Your pipeline starts here'}</h3><p>${store.leads.length?'Try a different filter or search term.':'Add your first inquiry, set an estimated job value, and give it a follow-up date.'}</p><button class="btn" data-action="add-lead">${ico('plus')} Add lead</button></div>`}</div></section><p class="section-note" style="margin:12px 4px">${filtered.length} of ${store.leads.length} leads shown · Data saved only in this browser</p></div>`}
function quotesPage(){let list=[...store.quotes].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<div class="page">${heading('QUOTE BUILDER','Quote it. Win it.','Clean estimates in minutes, sent through your own email.',`<button class="btn" data-action="add-quote">${ico('plus')} Create quote</button>`)}<div class="toolbar"><div class="daytag">${ico('receipt','sm')} ${list.length} total quotes</div><div class="section-note">Quotes don't send automatically</div></div>${list.length?`<section class="quote-list">${list.map(q=>{let l=getLead(q.leadId);return `<article class="quote-card"><div class="smallrow"><span class="eyebrow">QUOTE #${esc(q.number||q.id.slice(0,5).toUpperCase())}</span>${badge(q.status)}</div><div><h3>${esc(l?.name||q.clientName||'Customer')}</h3><p>${esc(l?.service||'Service estimate')} · ${shortdate(q.createdAt.slice(0,10))}</p></div><div class="quote-total">${moneyExact(quoteTotal(q))}</div><div class="smallrow"><span class="muted tiny">${q.items.length} line item${q.items.length===1?'':'s'}</span><span class="muted tiny">Valid ${q.validDays||14} days</span></div><div class="actions"><button class="btn soft small" data-action="view-quote" data-id="${q.id}">View quote</button><button class="btn outline small" data-action="send-quote" data-id="${q.id}">${ico('mail','sm')} Email</button></div></article>`}).join('')}</section>`:`<div class="panel"><div class="empty-state"><div class="empty-art">${ico('receipt','lg')}</div><h3>Make your first quote</h3><p>Add a customer and build a professional itemized estimate with optional tax and discount.</p><button class="btn" data-action="add-quote">${ico('plus')} Create quote</button></div></div>`}</div>`}
function followupsPage(){
  const p=pending();
  const groupDefs=[['Overdue',p.filter(l=>l.followUpDate<today()),'overdue'],['Due today',p.filter(l=>l.followUpDate===today()),'today'],['Coming up',p.filter(l=>l.followUpDate>today()),'upcoming']];
  const sections=groupDefs.map(([title,items,cls])=>{
    if(!items.length)return '';
    const rows=items.map(l=>`<article class="follow-item"><div class="lead-main"><div class="miniavatar">${esc(initials(l.name))}</div><div><h4>${esc(l.name)} <span class="muted tiny" style="font-weight:500">· ${esc(l.service||'Inquiry')}</span></h4><p>${esc(shortdate(l.followUpDate))} · ${money(l.value)} potential job${l.email?' · Email available':''}</p></div></div><div class="follow-actions"><button class="btn outline small" data-action="copy-followup" data-id="${l.id}">${ico('copy','sm')} Copy text</button>${l.email?`<button class="btn outline small" data-action="email-followup" data-id="${l.id}">${ico('mail','sm')} Email</button>`:''}<button class="btn soft small" data-action="snooze" data-id="${l.id}">+2 days</button><button class="btn small" data-action="complete-followup" data-id="${l.id}">${ico('check','sm')} Done</button></div></article>`).join('');
    return `<section class="follow-section"><h3>${badge(cls)} &nbsp;${title} <span class="muted">(${items.length})</span></h3>${rows}</section>`;
  }).join('');
  return `<div class="page">${heading('YOUR FOLLOW-THROUGH','Keep leads warm.','One simple to-do list for conversations that matter.',`<button class="btn" data-action="add-lead">${ico('plus')} Add lead</button>`)}<div class="cards4" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('OVERDUE',overdue().length,'clock','Needs attention now',overdue().length?'dotwarn':'dotgood')}${metric('DUE TODAY',p.filter(l=>l.followUpDate===today()).length,'calendar','Scheduled for today')}${metric('UPCOMING',p.filter(l=>l.followUpDate>today()).length,'arrow','Already on your radar')}</div>${p.length?`<section class="follow-list">${sections}</section>`:`<div class="panel"><div class="empty-state"><div class="empty-art">${ico('check','lg')}</div><h3>You're all caught up.</h3><p>When you add a follow-up date to an active lead, it will show up here.</p><button class="btn" data-action="nav" data-view="leads">Go to leads ${ico('arrow','sm')}</button></div></div>`}<div class="info-note" style="margin-top:20px">${ico('info','sm')} Reminders appear here when you open the app. LEADCTRL does not send push notifications, texts, or emails automatically.</div></div>`;
}
function settingsPage(){let b=store.business;return `<div class="page">${heading('YOUR WORKSPACE','Make it yours.','Manage your business details and keep your data safe.')}<div class="settings-grid"><section class="panel setting-card"><h2>Business profile</h2><p>These details are used in your quotes and follow-up messages.</p><form id="settings-form" class="form-grid"><div class="field span2"><label>Business name *</label><input name="name" required maxlength="90" value="${esc(b.name)}"></div><div class="field"><label>Your name</label><input name="owner" maxlength="70" value="${esc(b.owner)}"></div><div class="field"><label>Business category</label><select name="service">${['Home services','Auto detailing','Lawn care & landscaping','Pressure washing','Cleaning','Other services'].map(s=>`<option ${b.service===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Business email</label><input type="email" name="email" maxlength="140" placeholder="you@yourbusiness.com" value="${esc(b.email)}"></div><div class="field"><label>Business phone</label><input name="phone" maxlength="45" placeholder="(555) 123-4567" value="${esc(b.phone)}"></div><div class="field span2"><button class="btn" style="align-self:start" type="submit">Save changes ${ico('check','sm')}</button></div></form></section><div class="stack"><section class="panel setting-card"><h2>Back up your workspace</h2><p>This version stores everything locally on your device. Export a backup regularly, especially before switching phones or clearing browser data.</p><div class="settings-actions"><button class="btn soft" data-action="export-json">${ico('download')} Export backup</button><label class="importbtn">${ico('upload')} Import backup<input id="import-json" type="file" accept="application/json,.json"></label><button class="btn outline" data-action="export-csv">${ico('download')} Export leads CSV</button></div></section><section class="panel setting-card"><h2>Add to your iPhone</h2><p>In Safari, tap <b>Share</b> → <b>Add to Home Screen</b> → <b>Add</b>. Launch it from your home screen like an app.</p><div class="info-note">${ico('lock','sm')} No account needed, but data does not sync across devices. Avoid entering highly sensitive personal information.</div></section></div></div><section class="dangerzone"><h3>Start fresh</h3><p>${store.demo?'You are in sample mode. Remove all sample leads and quotes to start with your own data.':'This permanently removes leads and quotes saved in this browser. Export a backup first.'}</p><button class="btn danger small" data-action="clear-data">${ico('trash','sm')} ${store.demo?'Clear sample data':'Delete all leads & quotes'}</button></section><p class="section-note" style="margin-top:15px">LEADCTRL MVP v1 · No cloud account, automated messages, or paid billing.</p></div>`}
function modal(){const type=ui.modal.type;let body='',heading='',subtitle='',wide=false,foot='';if(type==='add-lead'||type==='edit-lead'){
let l=type==='edit-lead'?getLead(ui.modal.id):null;heading=l?'Edit opportunity':'New opportunity';subtitle='Keep the important details and the next step together.';
body=`<form id="lead-form"><div class="form-grid"><div class="field"><label>Customer name *</label><input required name="name" maxlength="110" value="${esc(l?.name||'')}" placeholder="Alex Morgan" autofocus></div><div class="field"><label>Company (optional)</label><input name="company" maxlength="110" value="${esc(l?.company||'')}" placeholder="Northside Homes"></div><div class="field"><label>Email</label><input type="email" name="email" maxlength="140" value="${esc(l?.email||'')}" placeholder="alex@example.com"></div><div class="field"><label>Phone</label><input name="phone" maxlength="45" value="${esc(l?.phone||'')}" placeholder="(555) 000-0000"></div><div class="field"><label>Service requested *</label><input required name="service" maxlength="120" value="${esc(l?.service||'')}" placeholder="Driveway pressure washing"></div><div class="field"><label>Estimated job value ($)</label><input type="number" min="0" max="100000000" step=".01" name="value" value="${l?.value??''}" placeholder="350"></div><div class="field"><label>Lead stage</label><select name="status">${STATUS.map(s=>`<option value="${s}" ${l?.status===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><div class="field"><label>Follow-up date</label><input type="date" name="followUpDate" value="${esc(l?.followUpDate||offset(2))}"></div><div class="field span2"><label>How did they find you?</label><select name="source">${['Website','Phone call','Instagram','Facebook','Referral','Walk-in','Other'].map(s=>`<option ${l?.source===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field span2"><label>Notes</label><textarea name="notes" maxlength="2400" placeholder="What they asked for, address/area, next step...">${esc(l?.notes||'')}</textarea></div></div><div style="margin-top:19px;display:flex;justify-content:space-between;align-items:center;gap:10px">${l?`<button type="button" class="btn danger small" data-action="delete-lead" data-id="${l.id}">${ico('trash','sm')} Delete</button>`:'<span></span>'}<div style="display:flex;gap:8px"><button type="button" class="btn outline" data-action="close-modal">Cancel</button><button class="btn" type="submit">${l?'Save changes':'Add opportunity'} ${ico('arrow','sm')}</button></div></div></form>`}
else if(type==='view-lead'){let l=getLead(ui.modal.id);if(!l){ui.modal=null;return ''}heading=l.name;subtitle=l.company||'Opportunity details';let quotes=store.quotes.filter(q=>q.leadId===l.id);body=`<div class="detailtop"><div class="miniavatar">${esc(initials(l.name))}</div><div><h3>${esc(l.name)}</h3><p>${esc(l.service||'Service inquiry')} · ${badge(l.status)}</p></div></div><div class="detailinfo">${[['Potential job value',money(l.value)],['Email',l.email||'Not provided'],['Phone',l.phone||'Not provided'],['Source',l.source||'Unknown'],['Follow-up',l.followUpDate?(datefmt(l.followUpDate)+(l.followUpDone?' · Done':'')):'Not scheduled'],['Added',datefmt(l.createdAt.slice(0,10))]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><strong style="text-align:right;overflow-wrap:anywhere">${esc(b)}</strong></div>`).join('')}</div>${l.notes?`<div class="note-box">${esc(l.notes).replace(/\n/g,'<br>')}</div>`:''}${quotes.length?`<p class="eyebrow" style="margin:20px 0 7px">LINKED QUOTES</p>${quotes.map(q=>`<div class="lead-row" data-action="view-quote" data-id="${q.id}"><div class="lead-main">${ico('receipt')} <strong>#${esc(q.number)} · ${moneyExact(quoteTotal(q))}</strong></div>${badge(q.status)}</div>`).join('')}`:''}<div class="divider" style="margin:20px 0"></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="edit-lead" data-id="${l.id}">${ico('edit','sm')} Edit details</button><button class="btn soft" data-action="add-quote" data-lead="${l.id}">${ico('plus','sm')} Make quote</button>${l.email?`<button class="btn outline" data-action="email-followup" data-id="${l.id}">${ico('mail','sm')} Email</button>`:''}${l.phone?`<a class="btn outline" href="tel:${esc(l.phone.replace(/[^\d+]/g,''))}">${ico('phone','sm')} Call</a>`:''}</div>`}
else if(type==='add-quote'||type==='edit-quote'){wide=true;let q=type==='edit-quote'?getQuote(ui.modal.id):null;heading=q?'Edit quote':'Create a quote';subtitle='An itemized estimate your customer can actually understand.';let options=store.leads.map(l=>`<option value="${l.id}" ${(q?.leadId||ui.quoteLead)===l.id?'selected':''}>${esc(l.name)} · ${esc(l.service||'Service')}</option>`).join('');if(!ui.quoteLines.length)ui.quoteLines=q?structuredClone(q.items):[{description:'',quantity:1,unitPrice:0}];body=`<form id="quote-form"><div class="form-grid"><div class="field span2"><label>Customer *</label><select id="quote-client" name="leadId" required><option value="">Choose a customer</option>${options}</select>${!store.leads.length?`<span class="hint">Add a lead first to make a quote.</span>`:''}</div><div class="field span2"><label>Line items</label><div style="display:grid;grid-template-columns:minmax(0,1fr) 48px 80px 27px;gap:4px;margin-bottom:5px"><span class="tiny muted">Service / description</span><span class="tiny muted">Qty</span><span class="tiny muted">Rate ($)</span></div><div id="quote-lines">${quoteLineHtml()}</div><button class="btn soft small" data-action="add-quote-line" type="button">${ico('plus','sm')} Add line item</button></div><div class="field"><label>Discount ($)</label><input id="quote-discount" type="number" min="0" max="100000000" step=".01" name="discount" value="${q?.discount||0}"></div><div class="field"><label>Tax rate (%)</label><input id="quote-tax" type="number" min="0" max="100" step=".01" name="taxRate" value="${q?.taxRate||0}"></div><div class="field"><label>Valid for (days)</label><input name="validDays" type="number" min="1" max="365" value="${q?.validDays||14}"></div><div class="field"><label>Quote status</label><select name="status">${['draft','sent','accepted','declined'].map(s=>`<option ${q?.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field span2"><label>Note to customer</label><textarea name="notes" maxlength="1800" placeholder="Thanks for reaching out! Here's your estimate...">${esc(q?.notes||'Thanks for considering us. Reach out with any questions.')}</textarea></div></div><div class="totalbox"><span class="em">Estimated total</span><strong id="quote-total-live">$0.00</strong></div><div style="display:flex;justify-content:end;gap:8px"><button class="btn outline" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit" ${!store.leads.length?'disabled':''}>${q?'Save quote':'Create quote'} ${ico('arrow','sm')}</button></div></form>`}
else if(type==='view-quote'){let q=getQuote(ui.modal.id);if(!q){ui.modal=null;return ''}let l=getLead(q.leadId);heading=`Quote #${esc(q.number)}`;subtitle=`${esc(l?.name||q.clientName||'Customer')} · ${datefmt(q.createdAt.slice(0,10))}`;wide=true;body=`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:18px"><div><span class="eyebrow">ISSUED BY</span><h3 style="margin:6px 0">${esc(store.business.name)}</h3><p class="small muted">${esc(store.business.email||store.business.phone||store.business.service)}</p></div>${badge(q.status)}</div><div class="detailinfo"><div class="detailrow"><span>Service</span><strong>${esc(l?.service||'Service work')}</strong></div>${q.items.map(i=>`<div class="detailrow"><span>${esc(i.description)}<br><small class="muted">${i.quantity} × ${moneyExact(i.unitPrice)}</small></span><strong>${moneyExact((+i.quantity||0)*(+i.unitPrice||0))}</strong></div>`).join('')}<div class="detailrow"><span>Discount / tax</span><strong>−${moneyExact(q.discount||0)} / ${Number(q.taxRate)||0}%</strong></div><div class="detailrow" style="background:#f5f9ef"><strong>TOTAL</strong><strong style="font-size:20px">${moneyExact(quoteTotal(q))}</strong></div></div>${q.notes?`<div class="note-box">${esc(q.notes)}</div>`:''}<div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:20px"><button class="btn" data-action="send-quote" data-id="${q.id}">${ico('mail','sm')} Compose email</button><button class="btn outline" data-action="print-quote" data-id="${q.id}">${ico('print','sm')} Print / PDF</button><button class="btn soft" data-action="edit-quote" data-id="${q.id}">${ico('edit','sm')} Edit</button><button class="btn danger" data-action="delete-quote" data-id="${q.id}">${ico('trash','sm')}</button></div><p class="hint" style="margin:16px 0 0">Emails open in your mail app for your review. LEADCTRL does not automatically send a message or collect payment.</p>`}
return `<div class="overlay" data-overlay="1"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><header class="modal-header"><div><span class="eyebrow">LEADCTRL</span><h2>${heading}</h2><p>${subtitle}</p></div><button class="btn soft icon-btn" data-action="close-modal" aria-label="Close dialog">${ico('x')}</button></header><div class="modal-body">${body}</div>${foot}</section></div>`}
function quoteLineHtml(){return ui.quoteLines.map((l,i)=>`<div class="line-item" data-line-index="${i}"><input aria-label="Item description" data-line-field="description" data-index="${i}" maxlength="150" placeholder="Service description" value="${esc(l.description)}" required><input aria-label="Quantity" data-line-field="quantity" data-index="${i}" type="number" min=".01" max="100000" step=".01" value="${+l.quantity||1}" required><input aria-label="Unit price" data-line-field="unitPrice" data-index="${i}" type="number" min="0" max="100000000" step=".01" value="${+l.unitPrice||0}" required><button class="remove-line" type="button" data-action="remove-quote-line" data-index="${i}" aria-label="Remove item">${ico('x','sm')}</button></div>`).join('')}
function quoteTotal(q){let subtotal=(q.items||[]).reduce((s,l)=>s+(+l.quantity||0)*(+l.unitPrice||0),0);let after=Math.max(0,subtotal-(+q.discount||0));return Math.round((after*(1+(+q.taxRate||0)/100)+Number.EPSILON)*100)/100}
function refreshQuoteMath(){const el=document.getElementById('quote-total-live');if(!el)return;const discount=parseFloat(document.getElementById('quote-discount')?.value)||0;const taxRate=parseFloat(document.getElementById('quote-tax')?.value)||0;el.textContent=moneyExact(quoteTotal({items:ui.quoteLines,discount,taxRate}));}
function sampleData(){const b={name:'Northside Services',owner:'Alex',email:'hello@northside.example',phone:'',service:'Home services'};const rows=[['Jordan Parker','Patio pressure washing',420,'quoted',-2,'Referral'],['Sam Chen','Driveway cleaning',320,'contacted',0,'Website'],['Taylor Reed','Exterior house wash',780,'new',1,'Instagram'],['Riley Brooks','Deck restoration',1450,'quoted',2,'Facebook'],['Casey Morgan','Gutter cleaning',230,'won',null,'Referral'],['Avery Hughes','Window cleaning',260,'contacted',3,'Website'],['Drew Foster','Roof soft wash',1200,'new',5,'Phone call'],['Morgan Ellis','Garage cleaning',180,'lost',null,'Other']];let leads=rows.map(([name,service,value,status,days,source],i)=>({id:randId(),name,company:'',email:`${name.toLowerCase().replace(' ','.')}@example.com`,phone:'',service,value,status,followUpDate:days===null?'':offset(days),followUpDone:false,source,notes:i===0?'Asked whether the patio can be finished by Friday.':'',createdAt:new Date(Date.now()-(i+1)*86400000).toISOString(),updatedAt:new Date(Date.now()-(i+1)*86400000).toISOString()}));let quotes=[{id:randId(),number:'1001',leadId:leads[0].id,clientName:leads[0].name,items:[{description:'Patio pressure wash',quantity:1,unitPrice:420}],discount:0,taxRate:0,validDays:14,status:'sent',notes:'Example quote only. No real customer.',createdAt:nowstamp()},{id:randId(),number:'1002',leadId:leads[3].id,clientName:leads[3].name,items:[{description:'Deck restoration',quantity:1,unitPrice:1450}],discount:50,taxRate:0,validDays:14,status:'draft',notes:'Example quote only. No real customer.',createdAt:nowstamp()}];return {version:1,business:b,leads,quotes,demo:true,activities:[]}}
function render(){const app=document.getElementById('app');app.innerHTML=ui.mode==='welcome'?welcomePage():ui.mode==='setup'?setupPage():appShell();if(ui.modal){const auto=document.querySelector('.modal [autofocus]');if(auto)auto.focus({preventScroll:true});refreshQuoteMath()}}
function openModal(type,id,lead){ui.quoteLines=[];ui.quoteLead=lead||'';ui.modal={type,id:id||null};ui.sidebar=false;render()}
function closeModal(){ui.modal=null;ui.quoteLines=[];render()}
function nav(v){if(!['overview','leads','quotes','followups','settings'].includes(v))return;ui.view=v;ui.modal=null;ui.sidebar=false;window.scrollTo(0,0);render()}
function contactText(l){return `Hi ${l.name.trim().split(' ')[0]}, it's ${store.business.owner||store.business.name} from ${store.business.name}. Just checking in about your ${l.service||'project'} request. Happy to answer any questions or help with next steps!`}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Follow-up message copied.')}catch{const ta=document.createElement('textarea');ta.value=s;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');toast('Follow-up message copied.')}catch{toast('Copy unavailable on this browser.')}ta.remove()}}
function emailFollowup(l){if(!l.email){toast('Add a customer email first.');return}const subject=`Following up about ${l.service||'your project'}`;location.href=`mailto:${encodeURIComponent(l.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(contactText(l))}`;toast('Opening your email app. Review before sending.')}
function quoteBody(q){let l=getLead(q.leadId);return `Hi ${l?.name?.split(' ')[0]||'there'},\n\nThanks for contacting ${store.business.name}. Here is your estimate:\n\nQUOTE #${q.number}\n${q.items.map(i=>`${i.description} — ${i.quantity} x ${moneyExact(i.unitPrice)} = ${moneyExact(i.quantity*i.unitPrice)}`).join('\n')}\nDiscount: ${moneyExact(q.discount||0)}\nTax rate: ${+q.taxRate||0}%\nTOTAL: ${moneyExact(quoteTotal(q))}\nValid for ${q.validDays||14} days.\n\n${q.notes||''}\n\nThank you,\n${store.business.owner||store.business.name}\n${store.business.name}${store.business.phone?'\n'+store.business.phone:''}`}
function sendQuote(q){const l=getLead(q.leadId);if(!l?.email){copyText(quoteBody(q));toast('No email for this lead. Quote copied instead.');return}location.href=`mailto:${encodeURIComponent(l.email)}?subject=${encodeURIComponent(`Quote #${q.number} from ${store.business.name}`)}&body=${encodeURIComponent(quoteBody(q))}`;toast('Opening mail app. You must press Send yourself.')}
function printQuote(q){let l=getLead(q.leadId);let subtotal=q.items.reduce((s,i)=>s+(+i.quantity||0)*(+i.unitPrice||0),0);let page=`<!doctype html><html><head><meta charset="utf-8"><title>Quote ${esc(q.number)}</title><style>body{font:14px Arial,sans-serif;color:#24313a;padding:45px;max-width:850px;margin:auto}header{display:flex;justify-content:space-between;margin-bottom:45px}h1{font-size:35px;letter-spacing:-2px;margin:0}h2{font-size:23px}small{color:#75858c}table{width:100%;border-collapse:collapse;margin:30px 0}th{text-align:left;background:#f0f4f0;padding:14px}td{padding:14px;border-bottom:1px solid #e5e9e5}.right{text-align:right}.total{font-size:26px;font-weight:800}footer{border-top:1px solid #e5e9e5;padding-top:23px;color:#6b7b7c;line-height:1.6}</style></head><body><header><div><h1>${esc(store.business.name)}</h1><small>${esc(store.business.email||'')} ${esc(store.business.phone||'')}</small></div><div class="right"><h2>ESTIMATE</h2><small>Quote #${esc(q.number)}<br>${esc(datefmt(q.createdAt.slice(0,10)))}<br>Valid ${+q.validDays||14} days</small></div></header><div><small>PREPARED FOR</small><h2>${esc(l?.name||q.clientName||'Customer')}</h2><small>${esc(l?.email||'')}</small></div><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th class="right">Amount</th></tr></thead><tbody>${q.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${esc(i.quantity)}</td><td>${moneyExact(i.unitPrice)}</td><td class="right">${moneyExact(i.quantity*i.unitPrice)}</td></tr>`).join('')}</tbody></table><div class="right">Subtotal: ${moneyExact(subtotal)}<br>Discount: −${moneyExact(q.discount||0)}<br>Tax: ${+q.taxRate||0}%<p class="total">Total: ${moneyExact(quoteTotal(q))}</p></div><footer><strong>Notes</strong><p>${esc(q.notes||'Thank you for considering us.').replace(/\n/g,'<br>')}</p>This is an estimate, not an invoice or payment receipt.</footer><script>window.addEventListener('load',()=>{setTimeout(()=>window.print(),300)})<\/script></body></html>`;const win=window.open('','_blank');if(!win){toast('Allow popups to print your quote.');return}win.document.open();win.document.write(page);win.document.close();}
function downloadFile(name,contents,type){const blob=new Blob([contents],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function exportJson(){downloadFile(`leadctrl-backup-${today()}.json`,JSON.stringify({...store,exportedAt:nowstamp()},null,2),'application/json');toast('Backup exported. Save it somewhere safe.')}
function exportCsv(){const cols=['Name','Company','Email','Phone','Service','Value','Status','Source','Follow-up','Follow-up complete','Notes','Created'];const csv=[cols,...store.leads.map(l=>[l.name,l.company,l.email,l.phone,l.service,l.value,l.status,l.source,l.followUpDate,l.followUpDone,l.notes,l.createdAt])].map(row=>row.map(value=>`"${(String(value??'').match(/^[=+@\-\t\r]/)?"'"+String(value??''):String(value??'')).replace(/"/g,'""')}"`).join(',')).join('\r\n');downloadFile(`leadctrl-leads-${today()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');toast('Lead list exported to CSV.')}
function changeLead(l,fields){Object.assign(l,fields,{updatedAt:nowstamp()});save();render()}
function handleClick(e){const a=e.target.closest('[data-action]');if(!a){if(e.target.matches('[data-overlay]'))closeModal();const tr=e.target.closest('tr[data-open]');if(tr)openModal('view-lead',tr.dataset.open);return}const k=a.dataset.action;const id=a.dataset.id;const lead=getLead(id);const quote=getQuote(id);if(a.closest('.overlay')&&k==='nav')closeModal();switch(k){
case 'start-setup':ui.mode='setup';render();break;
case 'start-demo':store=sampleData();save();ui.mode='app';ui.view='overview';render();toast('Demo loaded. All customers are fictional.');break;
case 'back-welcome':ui.mode='welcome';render();break;
case 'toggle-menu':ui.sidebar=!ui.sidebar;render();break;
case 'nav':nav(a.dataset.view);break;
case 'filter':ui.filter=a.dataset.status;render();break;
case 'add-lead':openModal('add-lead');break;
case 'edit-lead':openModal('edit-lead',id);break;
case 'view-lead':openModal('view-lead',id);break;
case 'add-quote':if(!store.leads.length){toast('Add your first lead before making a quote.');openModal('add-lead');break}openModal('add-quote',null,a.dataset.lead);break;
case 'view-quote':openModal('view-quote',id);break;
case 'edit-quote':openModal('edit-quote',id);break;
case 'close-modal':closeModal();break;
case 'add-quote-line':ui.quoteLines.push({description:'',quantity:1,unitPrice:0});document.getElementById('quote-lines').innerHTML=quoteLineHtml();refreshQuoteMath();break;
case 'remove-quote-line':if(ui.quoteLines.length<=1){toast('Keep at least one item.');break}ui.quoteLines.splice(+a.dataset.index,1);document.getElementById('quote-lines').innerHTML=quoteLineHtml();refreshQuoteMath();break;
case 'complete-followup':if(lead){changeLead(lead,{followUpDone:true});toast('Follow-up marked complete.')}break;
case 'snooze':if(lead){let date=lead.followUpDate&&lead.followUpDate>today()?lead.followUpDate:today();const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+2);changeLead(lead,{followUpDate:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,followUpDone:false});toast('Follow-up moved two days ahead.')}break;
case 'copy-followup':if(lead)copyText(contactText(lead));break;
case 'email-followup':if(lead)emailFollowup(lead);break;
case 'send-quote':if(quote)sendQuote(quote);break;
case 'print-quote':if(quote)printQuote(quote);break;
case 'delete-lead':if(lead&&confirm(`Delete ${lead.name} and their linked quotes? This cannot be undone.`)){store.leads=store.leads.filter(l=>l.id!==id);store.quotes=store.quotes.filter(q=>q.leadId!==id);save();ui.modal=null;render();toast('Lead and linked quotes deleted.')}break;
case 'delete-quote':if(quote&&confirm('Delete this quote? This cannot be undone.')){store.quotes=store.quotes.filter(q=>q.id!==id);save();ui.modal=null;render();toast('Quote deleted.')}break;
case 'export-json':exportJson();break;
case 'export-csv':exportCsv();break;
case 'clear-data':if(confirm('Permanently delete all saved leads, quotes and sample data from this device? Export a backup first if needed.')){store.leads=[];store.quotes=[];store.activities=[];store.demo=false;save();ui.modal=null;nav('overview');toast('Workspace cleared.');}break;
}}
function handleSubmit(e){let form=e.target;if(!['setup-form','lead-form','quote-form','settings-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form);if(form.id==='setup-form'){store.business.name=String(f.get('name')||'').trim();store.business.owner=String(f.get('owner')||'').trim();store.business.service=f.get('service')||'Home services';if(!store.business.name){toast('Enter a business name.');return}store.demo=false;save();ui.mode='app';render();toast('Your workspace is ready.');return}if(form.id==='settings-form'){for(const k of ['name','owner','email','phone','service'])store.business[k]=String(f.get(k)||'').trim();save();render();toast('Business profile saved.');return}if(form.id==='lead-form'){const l=ui.modal.type==='edit-lead'?getLead(ui.modal.id):null;let name=String(f.get('name')||'').trim(),service=String(f.get('service')||'').trim();if(!name||!service){toast('Customer name and service are required.');return}let data={name,company:String(f.get('company')||'').trim(),email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),service,value:Math.max(0,Number(f.get('value'))||0),status:f.get('status')||'new',source:String(f.get('source')||''),followUpDate:String(f.get('followUpDate')||''),notes:String(f.get('notes')||'').trim()};if(l){data.followUpDone=l.followUpDate===data.followUpDate?l.followUpDone:false;Object.assign(l,data,{updatedAt:nowstamp()});activity('lead',`Updated ${name}`)}else{store.leads.unshift({...data,id:randId(),followUpDone:false,createdAt:nowstamp(),updatedAt:nowstamp()});activity('lead',`Added ${name}`)}save();ui.modal=null;render();toast(l?'Lead updated.':'Lead added to your pipeline.');return}if(form.id==='quote-form'){const leadId=String(f.get('leadId')||'');const customer=getLead(leadId);if(!customer){toast('Choose a customer first.');return}if(!ui.quoteLines.length||ui.quoteLines.some(l=>!l.description.trim()||!(Number(l.quantity)>0)||Number(l.unitPrice)<0)){toast('Add a description, quantity and valid price for each item.');return}const items=ui.quoteLines.map(l=>({description:l.description.trim(),quantity:Number(l.quantity),unitPrice:Number(l.unitPrice)}));const discount=Math.max(0,Number(f.get('discount'))||0),taxRate=Math.max(0,Math.min(100,Number(f.get('taxRate'))||0));const base=items.reduce((n,l)=>n+l.quantity*l.unitPrice,0);if(discount>base){toast('Discount cannot exceed the subtotal.');return}const q=ui.modal.type==='edit-quote'?getQuote(ui.modal.id):null;const data={leadId,clientName:customer.name,items,discount,taxRate,status:f.get('status')||'draft',validDays:Math.max(1,Math.min(365,Number(f.get('validDays'))||14)),notes:String(f.get('notes')||'').trim()};if(q){Object.assign(q,data,{updatedAt:nowstamp()});activity('quote',`Updated quote #${q.number}`)}else{const numbers=store.quotes.map(q=>parseInt(q.number,10)).filter(Number.isFinite);const number=String(Math.max(1000,...numbers)+1);store.quotes.unshift({...data,id:randId(),number,createdAt:nowstamp(),updatedAt:nowstamp()});activity('quote',`Created quote #${number}`)}if(customer.status==='new'||customer.status==='contacted')customer.status='quoted';customer.updatedAt=nowstamp();save();ui.modal=null;ui.quoteLines=[];nav('quotes');toast(q?'Quote updated.':'Quote created. Ready to review and send.');return}}
function validateImport(data){if(!data||typeof data!=='object'||!data.business||typeof data.business.name!=='string'||!Array.isArray(data.leads)||!Array.isArray(data.quotes))return false;if(data.leads.length>20000||data.quotes.length>20000)return false;return data.leads.every(l=>l&&typeof l.id==='string'&&typeof l.name==='string'&&STATUS.includes(l.status))&&data.quotes.every(q=>q&&typeof q.id==='string'&&Array.isArray(q.items));}
function handleChange(e){if(e.target.id==='import-json'){const f=e.target.files[0];if(!f)return;if(f.size>8e6){toast('Backup is too large. Maximum 8 MB.');return}f.text().then(s=>{let d;try{d=JSON.parse(s)}catch{toast('Invalid JSON file.');return}if(!validateImport(d)){toast('This is not a valid LEADCTRL backup.');return}if(!confirm('Import this backup? It will replace leads, quotes and business details on this device.'))return;store={version:1,business:d.business,leads:d.leads,quotes:d.quotes,activities:Array.isArray(d.activities)?d.activities.slice(0,60):[],demo:!!d.demo};save();ui.mode='app';nav('overview');toast('Backup restored.');}).catch(()=>toast('Could not read backup.'));e.target.value='';}}
function handleInput(e){if(e.target.id==='lead-search'){ui.search=e.target.value;const pos=e.target.selectionStart;render();let el=document.getElementById('lead-search');el?.focus();el?.setSelectionRange(pos,pos);return}if(e.target.matches('[data-line-field]')){const i=+e.target.dataset.index;const fld=e.target.dataset.lineField;if(ui.quoteLines[i])ui.quoteLines[i][fld]=e.target.type==='number'?Number(e.target.value):e.target.value;refreshQuoteMath();return}if(e.target.id==='quote-discount'||e.target.id==='quote-tax')refreshQuoteMath()}
document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal)closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-open]')){e.preventDefault();openModal('view-lead',e.target.dataset.open)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('div[data-action="view-lead"][role="button"]')){e.preventDefault();openModal('view-lead',e.target.dataset.id)}});
render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();